import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../api/beissab_api.dart';import '../widgets/common.dart';
class PlanScreen extends StatefulWidget{const PlanScreen({super.key});@override State<PlanScreen> createState()=>_S();}class _S extends State<PlanScreen>{Map<String,dynamic>? week;bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{week=await weekApi.active();}catch(_){week=null;}finally{if(mounted)setState(()=>loading=false);}}dynamic recipe(dynamic d){if(d is! Map)return null;return d['recipe']??d['meal']??d['menu']??((d['recipes'] is List&&(d['recipes'] as List).isNotEmpty)?d['recipes'][0]:null);}@override Widget build(c){final days=(week?['days'] as List?)??[];return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.only(bottom:110),children:[const PageTitle('Wochenplan',subtitle:'Deine ausgewählten Gerichte für die Woche.'),if(loading)const Center(child:CircularProgressIndicator())else if(days.isEmpty)Padding(padding:const EdgeInsets.all(20),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[const Text('Noch kein Wochenplan.'),const SizedBox(height:12),FilledButton(onPressed:()=>context.go('/app'),child:const Text('Gerichte auswählen'))]))))else ...days.asMap().entries.map((e){final d=e.value,m=recipe(d);final day=d is Map?(d['dayName']??d['name']??d['weekday']??'Tag ${e.key+1}'):'Tag ${e.key+1}';return Padding(padding:const EdgeInsets.fromLTRB(20,0,20,12),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(16),leading:CircleAvatar(child:Text('${e.key+1}')),title:Text('$day',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(m==null?'Noch frei':mealTitle(m)),trailing:m==null?null:const Icon(Icons.chevron_right),onTap:m==null?null:()=>context.push('/recipe/${mealId(m)}',extra:m))));}),if(days.isNotEmpty)Padding(padding:const EdgeInsets.all(20),child:OutlinedButton.icon(onPressed:()async{await weekApi.remove();await load();},icon:const Icon(Icons.delete_outline),label:const Text('Wochenplan löschen')))]));}}
